create extension if not exists pgcrypto;
create table if not exists public.course_certificate_settings(id uuid primary key default gen_random_uuid(),course_id text not null unique references public.courses(id) on delete cascade,certificate_title text not null default 'Certificate of Completion',completion_statement text not null default 'has successfully completed the course',cpd_hours numeric(6,2) not null default 0,issuer_name text not null default 'Kraken Medical Training',signatory_name text,signatory_role text,logo_url text,accent_style text not null default 'green',validity_months integer,enabled boolean not null default true,require_quiz boolean not null default true,show_score boolean not null default true,show_verification boolean not null default true,created_at timestamptz not null default now());
create table if not exists public.issued_certificates(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,course_id text not null references public.courses(id) on delete cascade,certificate_settings_id uuid references public.course_certificate_settings(id) on delete set null,verification_code text not null unique,learner_name text not null,course_title text not null,cpd_hours numeric(6,2) not null default 0,score integer,issued_at timestamptz not null default now(),expires_at timestamptz,revoked_at timestamptz,unique(user_id,course_id));
create table if not exists public.cpd_reflections(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,course_id text references public.courses(id) on delete set null,title text not null default 'CPD reflection',experience text not null,learning text not null,action_plan text not null,created_at timestamptz not null default now());
alter table public.course_certificate_settings enable row level security;alter table public.issued_certificates enable row level security;alter table public.cpd_reflections enable row level security;
drop policy if exists "Certificate settings readable" on public.course_certificate_settings;create policy "Certificate settings readable" on public.course_certificate_settings for select using(enabled=true);
drop policy if exists "Admins manage certificate settings" on public.course_certificate_settings;create policy "Admins manage certificate settings" on public.course_certificate_settings for all using(exists(select 1 from public.profiles p where p.id=auth.uid() and p.role in('admin','instructor'))) with check(exists(select 1 from public.profiles p where p.id=auth.uid() and p.role in('admin','instructor')));
drop policy if exists "Learners read own certificates" on public.issued_certificates;create policy "Learners read own certificates" on public.issued_certificates for select using(auth.uid()=user_id);
drop policy if exists "Learners create own certificates" on public.issued_certificates;create policy "Learners create own certificates" on public.issued_certificates for insert with check(auth.uid()=user_id);
drop policy if exists "Learners read own reflections" on public.cpd_reflections;create policy "Learners read own reflections" on public.cpd_reflections for select using(auth.uid()=user_id);
drop policy if exists "Learners create own reflections" on public.cpd_reflections;create policy "Learners create own reflections" on public.cpd_reflections for insert with check(auth.uid()=user_id);